/**
 * 키워드로 에셋 검색
 * @param query - 검색 키워드 (공백으로 분리)
 * @returns 매칭된 에셋 경로 배열 (점수 내림차순, 최대 10개)
 */
export function searchAssets(query: string): string[] {
    const queryWords = query.toLowerCase().split(/[\\s_\\-]+/).filter(w => w.length > 1);
    if (queryWords.length === 0) return [];
    const scored: [number, string][] = [];
    for (const [assetPath, kwStr] of SEARCHABLE_ASSETS) {
        const keywords = kwStr.split(",");
        let score = 0;
        for (const qw of queryWords) {
            for (const kw of keywords) {
                if (kw === qw) { score += 3; }
                else if (kw.includes(qw)) { score += 2; }
                else if (qw.includes(kw)) { score += 1; }
            }
        }
        if (score > 0) { scored.push([score, assetPath]); }
    }
    scored.sort((a, b) => b[0] - a[0]);
    return scored.slice(0, 10).map(s => s[1]);
}
